/** Commands that start, list, and read sessions and logs, locally or hosted. */
import { cmdCost, cmdLogs, cmdPlayground, cmdRun, cmdSession, cmdSessions, cmdTrajectory, } from "../../cli-ax.js";
import { defineCommand, hasFlag, positionalAsFlag, positionalIndex, } from "../command.js";
import { CliUsageError } from "../errors.js";
import { apiKeyFlag, bearerTokenFlag, dirFlag, dryRunFlag, fieldsFlag, jsonFlag, limitFlags, prodFlag, sessionFlags, slugFlag, teamFlag, textFlag, timeoutFlag, urlFlag, } from "../flags.js";
import { listValues, parseFields } from "../output.js";
import { loadMessages } from "./develop.js";
/** Where a session read goes: local server, --url, or --prod. */
const readTargetFlags = {
    ...dirFlag,
    ...urlFlag,
    ...prodFlag,
    ...teamFlag,
    ...apiKeyFlag,
    ...slugFlag,
    ...bearerTokenFlag,
};
const sessionArg = {
    name: "sessionId",
    description: "Session id (ses_…).",
    kind: "sessionId",
};
function sendsMessage(rest) {
    return hasFlag(rest, "message", "messages-file");
}
function hasSessionFlag(rest) {
    return hasFlag(rest, "session", "session-id");
}
/** `--session <id>`, `--session-id <id>`, or `--session=<id>` moved to the front as a positional id. */
function sessionFlagToPositional(rest) {
    const out = [];
    let id;
    for (let index = 0; index < rest.length; index++) {
        const arg = rest[index] ?? "";
        if ((arg === "--session" || arg === "--session-id") && index + 1 < rest.length) {
            id = rest[index + 1];
            index++;
            continue;
        }
        const inline = /^--session(?:-id)?=(.*)$/.exec(arg);
        if (inline !== null) {
            id = inline[1];
            continue;
        }
        out.push(arg);
    }
    return id === undefined ? out : [id, ...out];
}
export const logsCommand = defineCommand({
    name: "logs",
    group: "develop",
    summary: "Tail agent logs. Follows until Ctrl-C unless --once.",
    description: `
Without --prod, tails the local server (or --url). --prod tails the output of
the hosted deployment's most recent sessions, each under a ==> ses_… <==
header. Pass a session id to tail only that session.`,
    args: [sessionArg],
    flags: {
        ...readTargetFlags,
        ...sessionFlags,
        once: { type: "boolean", description: "Print the current log buffer once and exit." },
        json: {
            type: "boolean",
            description: "Print NDJSON log events ({sessionId, line} with --prod).",
        },
    },
    effect: "read",
    examples: [
        "agent-sdk logs --prod --slug my-agent --once",
        "agent-sdk logs ses_abc --prod --slug my-agent",
    ],
    async run({ values, positionals }) {
        return cmdLogs({
            dir: values.dir,
            url: values.url,
            prod: values.prod,
            team: values.team,
            apiKey: values["api-key"],
            slug: values.slug,
            bearerToken: values["bearer-token"],
            sessionId: positionals[0] ?? values["session-id"] ?? values.session,
            json: values.json,
            once: values.once,
        });
    },
});
export const sessionListCommand = defineCommand({
    name: "session list",
    aliases: [
        "sessions",
        {
            name: "cost",
            now: "session list --view cost",
            when: (rest, flags) => positionalIndex(rest, flags) === -1 && !hasSessionFlag(rest),
            argv: (rest) => [...rest, "--view", "cost"],
        },
    ],
    group: "develop",
    parentSummary: "Start, list, and read sessions, locally or on the hosted deployment.",
    summary: "List sessions on a running agent or the hosted deployment.",
    description: `
Most recently active first. --json prints { items, nextPageToken }. --since
stops at a cutoff. --view cost prints token usage per session plus a total
(a running server only, not --prod).`,
    flags: {
        ...readTargetFlags,
        ...jsonFlag,
        ...limitFlags,
        ...fieldsFlag,
        since: {
            type: "string",
            value: "<24h|instant>",
            description: "Only sessions active since a duration ago (30m, 24h, 7d) or an ISO-8601 instant.",
        },
        view: {
            type: "string",
            value: "<view>",
            choices: ["sessions", "cost"],
            default: "sessions",
            description: "What to print for each session.",
        },
    },
    effect: "read",
    examples: ["agent-sdk session list --prod --slug my-agent --json --limit 5"],
    async run({ values }) {
        if (values.view === "cost") {
            return cmdCost(undefined, {
                dir: values.dir,
                url: values.url,
                prod: values.prod,
                slug: values.slug,
                bearerToken: values["bearer-token"],
                json: values.json,
            });
        }
        return cmdSessions({
            dir: values.dir,
            url: values.url,
            prod: values.prod,
            team: values.team,
            apiKey: values["api-key"],
            slug: values.slug,
            bearerToken: values["bearer-token"],
            json: values.json,
            ...listValues(values),
            since: values.since,
        });
    },
});
export const sessionGetCommand = defineCommand({
    name: "session get",
    aliases: [
        {
            name: "session",
            now: "session get <sessionId>",
            when: (rest, flags) => positionalIndex(rest, flags) !== -1 && !sendsMessage(rest),
        },
        {
            name: "cost",
            now: "session get <sessionId> --view cost",
            when: (rest, flags) => positionalIndex(rest, flags) !== -1 || hasSessionFlag(rest),
            argv: (rest) => [...sessionFlagToPositional(rest), "--view", "cost"],
        },
        {
            name: "playground",
            now: "session get [<sessionId>] --web",
            argv: (rest) => [...sessionFlagToPositional(rest), "--web"],
        },
        {
            name: "trajectory",
            now: "session get --file <file.ndjson>",
            argv: (rest) => rest.map((arg) => (arg === "--events" ? "--file" : arg)),
        },
    ],
    group: "develop",
    summary: "Show one session: its trajectory, raw events, or cost.",
    description: `
Reads a running server, --url, or with --prod the hosted deployment. --file
reads a saved events.ndjson trace instead (no server). --trace also writes the
raw NDJSON trace (the format \`agent-sdk run --trace\` writes). --web opens the
session in the playground.`,
    args: [sessionArg],
    flags: {
        ...readTargetFlags,
        json: { type: "boolean", description: "Print the view as JSON." },
        ...fieldsFlag,
        view: {
            type: "string",
            value: "<view>",
            choices: ["trajectory", "events", "cost"],
            description: "trajectory (default), events ({ sessionId, events } JSON), or cost (per-turn usage; running server only).",
        },
        file: {
            type: "string",
            value: "<file.ndjson>",
            kind: "path",
            description: "Read this saved trace instead of a server. Trajectory view only.",
        },
        trace: {
            type: "string",
            value: "<file.ndjson>",
            kind: "outputPath",
            description: "Write the raw NDJSON trace here instead of printing.",
        },
        web: {
            type: "boolean",
            description: "Open the session in the playground (the portal with --prod). Print its URL.",
        },
        print: { type: "boolean", description: "With --web: print the URL only. Do not open it." },
        events: { type: "boolean", hidden: true, description: "Older spelling of --view events." },
        out: {
            type: "string",
            hidden: true,
            kind: "outputPath",
            description: "Older spelling of --trace.",
        },
        ...textFlag,
    },
    effect: "read",
    examples: [
        "agent-sdk session get ses_abc --prod --slug my-agent --json",
        "agent-sdk session get --file .agent-serve/traces/ses_abc.ndjson",
    ],
    async run({ values, positionals }) {
        const sessionId = positionals[0];
        const view = values.view ?? (values.events === true ? "events" : "trajectory");
        if (values.file !== undefined) {
            if (sessionId !== undefined) {
                throw new CliUsageError("pass a session id or --file, not both");
            }
            if (view !== "trajectory") {
                throw new CliUsageError("--file reads the trajectory view only");
            }
            return cmdTrajectory({ dir: ".", events: values.file, json: values.json });
        }
        if (values.web === true) {
            return cmdPlayground({
                dir: values.dir,
                url: values.url,
                prod: values.prod,
                team: values.team,
                apiKey: values["api-key"],
                slug: values.slug,
                bearerToken: values["bearer-token"],
                sessionId,
                print: values.print,
            });
        }
        if (sessionId === undefined) {
            throw new CliUsageError("missing <sessionId> (or pass --file <file.ndjson>)");
        }
        if (view === "cost") {
            return cmdCost(sessionId, {
                dir: values.dir,
                url: values.url,
                prod: values.prod,
                slug: values.slug,
                bearerToken: values["bearer-token"],
                json: values.json,
            });
        }
        return cmdSession(sessionId, {
            dir: values.dir,
            url: values.url,
            prod: values.prod,
            team: values.team,
            apiKey: values["api-key"],
            slug: values.slug,
            bearerToken: values["bearer-token"],
            // The events view is JSON already.
            json: view === "events" ? undefined : values.json,
            fields: parseFields(values.fields),
            rawEvents: view === "events",
            out: values.trace ?? values.out,
        });
    },
});
export const sessionCreateCommand = defineCommand({
    name: "session create",
    aliases: [
        {
            name: "session",
            now: "session create --message …",
            when: sendsMessage,
            // The old positional id was the session to resume.
            argv: (rest, flags) => positionalAsFlag(rest, flags, "--session") ?? [...rest],
        },
    ],
    group: "develop",
    summary: "Send one message to the hosted deployment as a new or resumed session.",
    description: `
The control plane accepts a delivery and allocates the session later. --wait
polls the delivery until it names the session (exit 3, pending, if
--timeout-ms passes first; default 120000). Then read it with
\`agent-sdk session get <ses_> --prod\`. --session ses_… resumes that session.`,
    flags: {
        ...dirFlag,
        ...slugFlag,
        ...teamFlag,
        ...apiKeyFlag,
        message: {
            type: "string",
            multiple: true,
            value: "<text>",
            description: "The message to send. Exactly one.",
        },
        "messages-file": {
            type: "string",
            hidden: true,
            kind: "path",
            description: "JSON array with exactly one message.",
        },
        ...sessionFlags,
        wait: { type: "boolean", description: "Wait until the delivery names its session." },
        ...timeoutFlag,
        "read-only": {
            type: "boolean",
            description: "Send the hosted turn with side effects blocked.",
        },
        "as-of": {
            type: "string",
            value: "<instant>",
            description: "Freeze the session clock at this ISO-8601 instant with a zone.",
        },
        component: {
            type: "string",
            value: "<key>",
            description: "Wake this component, not the application default.",
        },
        prod: { type: "boolean", hidden: true, description: "No effect: this command is hosted." },
        ...jsonFlag,
        ...dryRunFlag,
    },
    effect: "write",
    examples: [
        'agent-sdk session create --slug my-agent --message "Summarize open PRs" --wait --json',
    ],
    async run({ values }) {
        const timeoutMs = values["timeout-ms"] === undefined ? undefined : Number.parseInt(values["timeout-ms"], 10);
        if (timeoutMs !== undefined && (Number.isNaN(timeoutMs) || timeoutMs <= 0)) {
            throw new CliUsageError(`invalid --timeout-ms: ${values["timeout-ms"]}`);
        }
        return cmdRun({
            dir: values.dir,
            prod: true,
            slug: values.slug,
            team: values.team,
            apiKey: values["api-key"],
            messages: await loadMessages(values.message, values["messages-file"]),
            sessionId: values["session-id"] ?? values.session,
            wait: values.wait,
            timeoutMs,
            json: values.json,
            readOnly: values["read-only"],
            asOf: values["as-of"],
            componentKey: values.component,
        });
    },
});
